const b = $input.first().json.body ?? $input.first().json;
const telefono = String(b.tel ?? b.telefono ?? '').replace(/\D/g, '');
const interes = b.interes ?? b.proposito ?? '';
let tag = b.tag;
if (!['inversionista','cazador','lista_espera'].includes(tag)) {
  if (interes === 'inversion' || interes === 'ambos') tag = 'inversionista';
  else if (interes === 'caza') tag = 'cazador';
  else tag = 'lista_espera';
}
if (!b.nombre || telefono.length < 10) {
  throw new Error('nombre y tel son obligatorios');
}
return [{ json: {
  nombre: String(b.nombre).trim(),
  telefono,
  email: (b.email ?? '').trim() || null,
  fuente: (b.fuente ?? 'landing-568').trim(),
  tag,
  proposito: interes || null
}}];

